    34→
    35→export enum RecoverResult {
    36→  // the recover is not attempted because we have less than `NUMBER_OF_COLUMNS / 2` columns
    37→  NotAttemptedLessThanHalf = "not_attempted_less_than_half",
    38→  // the recover is not attempted because it has full data columns
    39→  NotAttemptedFull = "not_attempted_full",
    40→  // the recover is a success and it helps resolve availability
    41→  SuccessResolved = "success_resolved",
    42→  // the recover is a success but it's late, availability is already resolved by either gossip or getBlobsV2
