    47→
    48→export type CustodyConfigOpts = {
    49→  nodeId: NodeId;
    50→  config: ChainForkConfig;
    51→  initialCustodyGroupCount?: number;
    52→};
    53→
    54→export class CustodyConfig {
    55→  /**
    56→   * The number of custody groups the node should subscribe to
    57→   */
    58→  targetCustodyGroupCount: number;
    59→
    60→  /**
    61→   * The custody columns the node should subscribe to
    62→   */
    63→  custodyColumns: ColumnIndex[];
    64→
    65→  /**
    66→   * Custody columns map which column maps to which index in the array of columns custodied
    67→   * with zero representing it is not custodied
    68→   */
    69→  custodyColumnsIndex: Uint8Array;
    70→
    71→  /**
    72→   * The number of custody groups the node will sample
    73→   */
    74→  sampledGroupCount: number;
    75→
    76→  /**
    77→   * Custody groups sampled by the node as part of custody sampling
    78→   */
    79→  sampleGroups: CustodyIndex[];
    80→
    81→  /**
    82→   * Data columns sampled by the node as part of custody sampling
    83→   * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/das-core.md#custody-sampling
    84→   *
    85→   * TODO: Consider race conditions if this updates during sync/backfill
    86→   */
    87→  sampledColumns: ColumnIndex[];
    88→
    89→  /**
    90→   * Subnets sampled by the node as part of custody sampling
    91→   */
    92→  sampledSubnets: number[];
    93→
    94→  private config: ChainForkConfig;
    95→  private nodeId: NodeId;
    96→
    97→  constructor(opts: CustodyConfigOpts) {
    98→    this.config = opts.config;
    99→    this.nodeId = opts.nodeId;
   100→    this.targetCustodyGroupCount = opts.initialCustodyGroupCount ?? this.config.CUSTODY_REQUIREMENT;
   101→    this.custodyColumns = getDataColumns(this.config, this.nodeId, this.targetCustodyGroupCount);
